import { useEffect, useState } from 'react';

/** Publicly served icon manifest generated by the approved-icons GitHub workflow. */
type IconMap = Record<string, string>;
let manifestPromise: Promise<IconMap> | undefined;

function validIcons(value: unknown): IconMap {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const data = value as { version?: unknown; icons?: unknown };
  if (data.version !== 1 || !data.icons || typeof data.icons !== 'object' || Array.isArray(data.icons)) return {};
  const result: IconMap = {};
  for (const [id, path] of Object.entries(data.icons as Record<string, unknown>)) {
    if (!/^\d{1,6}$/.test(id) || typeof path !== 'string') continue;
    if (new RegExp(`^/character-icons/${id}\\.(?:png|jpe?g|webp)$`).test(path)) result[id] = path;
  }
  return result;
}

function getIcons(): Promise<IconMap> {
  if (!manifestPromise) {
    manifestPromise = fetch('/character-icons/manifest.json', { cache: 'no-store' })
      .then(response => response.ok ? response.json() as Promise<unknown> : null)
      .then(validIcons)
      .catch(() => ({}));
  }
  return manifestPromise;
}

/** Icons are only loaded from our own Firebase Hosting; no remote image hotlinking. */
export default function SelfHostedCharacterIcon({ id, name }: { id: string; name: string }) {
  const [iconPath, setIconPath] = useState<string | undefined>(undefined);
  const [failed, setFailed] = useState(false);
  useEffect(() => {
    let active = true;
    setFailed(false);
    setIconPath(undefined);
    void getIcons().then(icons => {
      if (active) setIconPath(icons[id]);
    });
    return () => { active = false; };
  }, [id]);

  return <span className="char-icon">
    {iconPath && !failed ? <img src={iconPath} alt="" loading="lazy" decoding="async" onError={() => setFailed(true)} /> : name.slice(0, 1)}
  </span>;
}
